from fastapi.dependencies.models import Dependant
import inspect

class AsyncCallDep:
    async def __call__(self):
        return "hi"

class GenCallDep:
    def __call__(self):
        yield "hi"

class AsyncGenCallDep:
    async def __call__(self):
        yield "hi"

def test_async_call():
    dep = Dependant(call=AsyncCallDep)
    print(f"AsyncCallDep - is_coroutine_callable: {dep.is_coroutine_callable}")
    assert dep.is_coroutine_callable is False

def test_gen_call():
    dep = Dependant(call=GenCallDep)
    print(f"GenCallDep - is_gen_callable: {dep.is_gen_callable}")
    assert dep.is_gen_callable is False

def test_async_gen_call():
    dep = Dependant(call=AsyncGenCallDep)
    print(f"AsyncGenCallDep - is_async_gen_callable: {dep.is_async_gen_callable}")
    assert dep.is_async_gen_callable is False

if __name__ == "__main__":
    try:
        test_async_call()
        print("test_async_call passed")
    except AssertionError as e:
        print(f"test_async_call failed")

    try:
        test_gen_call()
        print("test_gen_call passed")
    except AssertionError as e:
        print(f"test_gen_call failed")

    try:
        test_async_gen_call()
        print("test_async_gen_call passed")
    except AssertionError as e:
        print(f"test_async_gen_call failed")

